"use strict";
// Generated by scripts/build-preload.js from the Android helper's coupons.js. Edit that file, not this one.
const { ipcRenderer } = require("electron");
const browser = { runtime: { sendMessage: (m) => ipcRenderer.invoke("coupons", String((m && m.site) || "")) } };
// Checkout coupon finder. When a page shows a coupon / promo / voucher field, a small "Find coupons" pill appears next to it.
// A tap asks the Lodica server for codes people post for this shop, then tries them one by one with the shop's own Apply
// button, reads the order total after each, and keeps the code that saves the most. Nothing runs until the pill is tapped.
// Shared by the Android helper (content script) and desktop (preload/coupons.js is generated from this file).
(() => {
  if (window !== window.top || !/^https?:$/.test(location.protocol)) return;
  const FIELD = /coupon|promo|voucher|discount|korting|actiecode|kortingscode|rabatt|gutschein|code.?promo|r[ée]duc|gift.?code|cadeau/i;
  const NOT_FIELD = /search|zoek|email|mail|phone|tel|zip|postal|post.?code|card|cvc|cvv|iban|name|address|city|newsletter/i;
  const APPLY = /^\s*(apply|toepassen|redeem|use|gebruik|gebruiken|activeer|activate|valideer|validate|valider|appliquer|einl[öo]sen|anwenden|ok|inwisselen|verzilveren|add|toevoegen|ajouter|submit code)\s*$/i;
  const NEVER = /order|pay|betaal|betalen|checkout|afrekenen|bestel|place|buy|kopen|continue|verder|next|volgende|confirm|bevestig/i;
  const TOTAL = /total|totaal|te betalen|to pay|amount due|order total|grand total|gesamt|montant|sum/i;
  const MONEY = /(?:€|\$|£|EUR|USD|GBP)\s*([0-9]{1,3}(?:[.,\s][0-9]{3})*(?:[.,][0-9]{2})?|[0-9]+(?:[.,][0-9]{2})?)|([0-9]{1,3}(?:[.,\s][0-9]{3})*(?:[.,][0-9]{2})|[0-9]+[.,][0-9]{2})\s*(?:€|EUR|\$|£)/;

  const ask = (site) => browser.runtime.sendMessage({ type: "coupons", site });
  const visible = (e) => { if (!e || !e.isConnected) return false; const r = e.getBoundingClientRect(); return r.width > 20 && r.height > 10 && getComputedStyle(e).visibility !== "hidden"; };
  const describe = (e) => [e.name, e.id, e.placeholder, e.getAttribute("aria-label"), e.getAttribute("autocomplete"),
    e.labels && e.labels[0] && e.labels[0].textContent].filter(Boolean).join(" ");
  function findField() {
    for (const e of document.querySelectorAll("input:not([type]),input[type=text],input[type=search]")) {
      const d = describe(e);
      if (FIELD.test(d) && !NOT_FIELD.test(d.replace(FIELD, "")) && visible(e) && !e.disabled && !e.readOnly) return e;
    }
    return null;
  }
  // The Apply button that belongs to the field: same small container, close by, and never anything that pays or orders.
  function applyButton(field) {
    let box = field.parentElement;
    for (let up = 0; box && up < 4; up++, box = box.parentElement) {
      const list = [...box.querySelectorAll("button,input[type=submit],input[type=button],[role=button],a")].filter((b) => b !== field && visible(b));
      const ok = list.filter((b) => { const t = (b.value || b.textContent || b.getAttribute("aria-label") || "").trim(); return APPLY.test(t) && !NEVER.test(t); });
      if (ok.length) {
        const f = field.getBoundingClientRect();
        ok.sort((a, b) => { const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect(); return Math.hypot(ra.left - f.right, ra.top - f.top) - Math.hypot(rb.left - f.right, rb.top - f.top); });
        const r = ok[0].getBoundingClientRect();
        if (Math.hypot(r.left - f.right, r.top - f.top) < 400) return ok[0];
      }
    }
    return null;
  }
  const num = (s) => {
    let t = String(s).replace(/\s/g, "");
    // 1.234,56 and 1,234.56 both become 1234.56
    if (/[.,]\d{2}$/.test(t)) { const dec = t.slice(-3).replace(",", "."); t = t.slice(0, -3).replace(/[.,]/g, "") + dec; } else t = t.replace(/[.,]/g, "");
    const n = parseFloat(t);
    return isFinite(n) ? n : null;
  };
  // The order total: the last money amount in the element that is labelled total and holds the fewest words.
  let cur$ = "€";
  function readTotal() {
    let best = null, bestLen = 1e9;
    for (const e of document.querySelectorAll("tr,li,div,p,dl,section,span")) {
      if (e.children.length > 12) continue;
      const t = e.textContent || "";
      if (t.length > 160 || !TOTAL.test(t) || /sub.?total|subtotaal|zwischensumme|sous.?total/i.test(t)) continue;
      const all = [...t.matchAll(new RegExp(MONEY, "g"))];
      if (!all.length || !visible(e)) continue;
      if (t.length < bestLen) { bestLen = t.length; const m = all[all.length - 1]; best = num(m[1] || m[2]); cur$ = (/€|EUR/.test(m[0]) ? "€" : /£|GBP/.test(m[0]) ? "£" : "$"); }
    }
    return best;
  }
  function setValue(field, v) {
    const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
    field.focus();
    set.call(field, v);
    field.dispatchEvent(new Event("input", { bubbles: true }));
    field.dispatchEvent(new Event("change", { bubbles: true }));
  }
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  // After Apply, wait until the page settles: a total change or two quiet moments without DOM changes.
  function settled(before) {
    return new Promise((res) => {
      let quiet = 0, ticks = 0, changed = false, done = false;
      const end = () => { if (done) return; done = true; obs.disconnect(); clearInterval(t); clearTimeout(cap); res(); };
      const obs = new MutationObserver(() => { quiet = 0; });
      obs.observe(document.body, { childList: true, subtree: true, characterData: true });
      // The total moved: one more tick so the page finishes drawing. Otherwise 1.2 s without DOM changes means the shop is done.
      const t = setInterval(() => {
        ticks++;
        if (readTotal() !== before) { if (changed) end(); changed = true; return; }
        if (++quiet >= 3 && ticks >= 2) end();
      }, 400);
      const cap = setTimeout(end, 6000);
    });
  }

  // ---- UI: one pill beside the Apply button that also shows the status. Own shadow root, so page styles cannot reach it.
  let host = null, root = null, pill = null, field = null, busy = false, stop = false;
  function ui() {
    if (host) return;
    host = document.createElement("lodica-coupons");
    host.style.cssText = "position:absolute;z-index:2147483646;left:0;top:0;transition:transform 180ms cubic-bezier(.33,1,.68,1)";
    root = host.attachShadow({ mode: "closed" });
    const dark = matchMedia("(prefers-color-scheme: dark)").matches;
    const st = document.createElement("style");
    st.textContent = `
      :host{all:initial}
      .w{display:flex;flex-direction:column;gap:4px;align-items:flex-start;font:500 13px/1.3 system-ui,sans-serif}
      button{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 12px;border-radius:999px;
        background:#F59E0B;color:#1A1300;font-weight:600;box-shadow:0 4px 14px rgba(0,0,0,.18);
        transform-origin:left center;animation:in 260ms cubic-bezier(.34,1.45,.64,1) both;transition:transform 120ms ease-out,background 120ms ease-out}
      button:hover{transform:scale(1.04)}button:active{transform:scale(.97)}button:focus-visible{outline:2px solid #F59E0B;outline-offset:2px}
      button.busy{background:${dark ? "#2B2E33" : "#FFFFFF"};color:${dark ? "#ECEDEE" : "#1B1C1F"}}
      button span{white-space:nowrap;transition:opacity 120ms ease-out}
      @keyframes in{from{opacity:0;transform:scale(.8)}to{opacity:1;transform:none}}
      @media (prefers-reduced-motion:reduce){button{animation:none;transition:none}}`;
    const w = document.createElement("div"); w.className = "w";
    pill = document.createElement("button");
    pill.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9a2 2 0 0 0 0 4v5h18v-5a2 2 0 0 1 0-4V6H3z"/><path d="M14 6v12" stroke-dasharray="2 2"/></svg><span>Find coupons</span>';
    pill.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); if (busy) stop = true; else run(); });
    w.append(pill);
    root.append(st, w);
    document.documentElement.appendChild(host);
  }
  function place() {
    if (!host || !field) return;
    // After the last thing on the field's row (Apply button, the shop's own "code applied" text), so it covers none of it.
    const r = field.getBoundingClientRect(), b = applyButton(field);
    let row = field.parentElement, right = r.right;
    while (row && b && !row.contains(b)) row = row.parentElement;
    for (const e of [...((row || field.parentElement || document.body).querySelectorAll("*"))].slice(0, 300)) {
      if (e === host) continue;
      const q = e.getBoundingClientRect();
      if (q.width && q.height && q.bottom > r.top + 4 && q.top < r.bottom - 4 && q.right < innerWidth - 40) right = Math.max(right, q.right);
    }
    const x = Math.min(right + 8, innerWidth - 220);
    host.style.transform = "translate(" + Math.round(x + scrollX) + "px," + Math.round(r.top + r.height / 2 - 16 + scrollY) + "px)";
  }
  // The pill is also the status: "Trying X…" while busy (a tap stops), then the result. A later tap runs it again.
  const label = (t) => { if (pill) pill.lastChild.textContent = t; };
  const say = (t) => { label(t); if (pill) pill.title = t; place(); };
  const fmt = (n) => cur$ + n.toLocaleString(document.documentElement.lang || undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  async function run() {
    if (!field || !field.isConnected) return;
    busy = true; stop = false; pill.classList.add("busy");
    say("Looking for codes…");
    let codes = [];
    try { const r = await ask(location.hostname); codes = (r && Array.isArray(r.codes) ? r.codes : []).map((c) => c.code).filter(Boolean); } catch (e) { /* offline */ }
    if (!codes.length) { say("No codes found for this shop"); busy = false; pill.classList.remove("busy"); return; }
    const btn = applyButton(field);
    if (!btn) {
      // No safe Apply button found: never guess and submit something. Show the codes to copy instead.
      say("Codes to try: " + codes.slice(0, 4).join(", "));
      busy = false; pill.classList.remove("busy"); return;
    }
    const start = readTotal();
    let best = null, bestTotal = start, tried = 0;
    for (const code of codes.slice(0, 10)) {
      if (stop || !field.isConnected) break;
      tried++;
      say("Trying " + code + " · " + tried + "/" + Math.min(10, codes.length));
      const before = readTotal();
      setValue(field, code);
      await sleep(150);
      const b = applyButton(field) || btn;
      if (!b.isConnected) break;
      b.click();
      await settled(before);
      const after = readTotal();
      if (after != null && (bestTotal == null || after < bestTotal - 0.004)) { best = code; bestTotal = after; }
      // Some shops replace the field after a code; follow it.
      if (!field.isConnected) { const f = findField(); if (!f) break; field = f; }
    }
    // End on the best code (the last one tried may have replaced it).
    if (best) {
      const cur = readTotal();
      if (cur == null || cur > bestTotal + 0.004) { setValue(field, best); await sleep(150); const b = applyButton(field); if (b) { b.click(); await settled(cur); } }
      say(start != null && bestTotal != null ? "Saved " + fmt(start - bestTotal) + " · " + best : "Applied " + best);
    } else say(stop ? "Stopped" : "No code lowered the total");
    busy = false; pill.classList.remove("busy");
  }

  // Watch for a coupon field cheaply: a check on load and a few later ones (checkouts render late), never a DOM observer.
  let checks = 0, on = null;
  async function check() {
    const f = findField();
    // Asked once per page, only when a field shows: is the finder switched on and is a server linked?
    if (f && on === null) { try { const r = await browser.runtime.sendMessage({ type: "coupons", site: "" }); on = !!(r && r.on); } catch (e) { on = false; } }
    if (f && on && f !== field) { field = f; ui(); place(); }
    if (!f && host && !busy) { host.remove(); host = null; field = null; }
    if (++checks < 8) setTimeout(check, checks < 3 ? 1500 : 4000);
  }
  addEventListener("scroll", () => { if (host) place(); }, { passive: true });
  addEventListener("resize", () => { if (host) place(); }, { passive: true });
  // Single-page checkouts: look again after a click (opening the "Have a code?" section) or a route change.
  addEventListener("click", (e) => { if (!host || !host.contains(e.target)) { checks = Math.min(checks, 6); setTimeout(check, 500); } }, true);
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", check, { once: true }); else check();
})();
